const PARAMS = { N: 2 ** 14, r: 8, p: 1 };
const VENTANA_MS = 60_000, MAX_FALLOS = 5;

function hashear(clave) {
  const sal = crypto.randomBytes(16);          // sal nueva por cuenta
  return sal.toString('hex') + '$' + crypto.scryptSync(clave, sal, 32, PARAMS).toString('hex');
}
function verificar(clave, guardado) {
  const [sal, h] = guardado.split('$');
  const calc = crypto.scryptSync(clave, Buffer.from(sal, 'hex'), 32, PARAMS);
  return crypto.timingSafeEqual(calc, Buffer.from(h, 'hex')); // compara sin filtrar por tiempo
}
